// Token机制实现
@RestController
public class OrderController {
    @Autowired
    private RedisTemplate<String, String> redisTemplate;

    @GetMapping("/token")
    public String getToken() {
        String token = UUID.randomUUID().toString();
        redisTemplate.opsForValue().set("idempotent:" + token, "1", 5, TimeUnit.MINUTES);
        return token;
    }

    @PostMapping("/order")
    public String createOrder(@RequestParam String token, @RequestBody OrderDTO dto) {
        String key = "idempotent:" + token;
        Boolean exists = redisTemplate.delete(key);
        if (!exists) {
            return "请勿重复提交";
        }
        // 创建订单
        return orderService.create(dto);
    }
}

// 唯一索引方案
@Service
public class PaymentService {
    @Transactional
    public void pay(PaymentDTO dto) {
        try {
            PaymentRecord record = new PaymentRecord();
            record.setOrderId(dto.getOrderId());
            record.setTransId(dto.getTransId()); // 唯一交易号
            paymentMapper.insert(record);
        } catch (DuplicateKeyException e) {
            // 重复支付，直接返回成功
            log.info("重复支付: {}", dto.getOrderId());
        }
    }
}
